import ast, pathlib, subprocess, sys; files=subprocess.check_output(["git","ls-files","*.py"], text=True).splitlines(); bad=[]; skipped=[]
for f in files:
    if "/vendor/" in f or f.startswith("harness/vendor/"):
        skipped.append(f); continue
    try:
        ast.parse(pathlib.Path(f).read_text(encoding="utf-8"), filename=f)
    except Exception as e:
        bad.append((f, str(e)))
print(f"python files parsed={len(files)-len(skipped)} skipped_vendor={len(skipped)} bad={len(bad)}")
for f,e in bad[:50]: print(f"BAD {f}: {e}")
sys.exit(1 if bad else 0)
